$seasonality$, E'\n') AS source(line)
CROSS JOIN LATERAL unnest(
    string_to_array(split_part(source.line, '|', 2), ',')
) WITH ORDINALITY AS month_weight(weight_multiplier, month)
JOIN ingredient_concept ic
  ON ic.code = split_part(source.line, '|', 1)
WHERE source.line <> ''
ON CONFLICT (ingredient_concept_id, month) DO NOTHING;
